CREATE COLUMN TABLE "TEST_AP"."OADF" ("Code" SMALLINT CS_INT NOT NULL , "Name" NVARCHAR(50) NOT NULL , "Format" NVARCHAR(100), "UserSign" SMALLINT CS_INT, "SuppBkLine" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OADF_ADF_NAME" ON "TEST_AP"."OADF" ( "Name" ASC )